mapper.select:
select fp.finprod_market_id as finprodId, fp.finprod_id as bondId, fp.finprod_abbr as bondName, fp.vdate as vdate, fp.mdate as mdate, fp.coupon_species as couponType, fpt.type_4 as bondType1, fpt.type_5 as bondType2, (fri.rate)*100 as rate, fri.basis as basis, fp.issue_price as price from FIN_PRODUCT fp left join FIN_PRODUCT_TYPE fpt on fp.finprod_id = fpt.finprod_id left join FIN_CASH_INFO fci on fci.finprod_id = fp.finprod_id and fci.finprod_type = #{finprodType} and fci.cash_type_2 = #{cashType} left join FIN_RATE_INFO fri on fri.cash_id = fci.cash_id and fri.eff_date = fp.vdate where fp.FINPROD_TYPE = #{finprodType}
AND vfp.finprod_id in
#{bond}
AND vfp.coupon_species in
#{couponType}
AND fpt.type_1 in
#{bondType1}
AND fpt.type_2 in
#{bondType2}
AND vfp.vdate >= to_date(#{vDateBegin},'yyyy-MM-dd')
AND vfp.vdate <=to_date(#{vDateEnd},'yyyy-MM-dd')
AND vfp.mdate >=to_date(#{mDateBegin},'yyyy-MM-dd')
AND vfp.mdate <= to_date(#{mDateEnd},'yyyy-MM-dd')

SELECT FINPROD_ID id, FINPROD_ABBR||':'||FINPROD_MARKET_ID text FROM FIN_PRODUCT
FINPROD_TYPE2 = #{assestType}
AND ( FIN_PRODUCT.FINPROD_ABBR LIKE CONCAT('%', CONCAT(#{search}, '%')) OR FIN_PRODUCT.FINPROD_MARKET_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND FINPROD_ID = #{initValue}
AND FINPROD_ID NOT IN( SELECT O_FINPROD_ID FROM FIN_PRODUCT WHERE O_FINPROD_ID IS NOT NULL )

SELECT
	INPUT_VALUE_1 inputValue1,
	INPUT_VALUE_2 inputValue2,
	INPUT_VALUE_3 inputValue3,
	INPUT_VALUE_4 inputValue4,
	INPUT_VALUE_5 inputValue5
FROM
    FIN_PRODUCT_TYPE_CONFIG
WHERE CONFIG_TYPE = #{configType}

    AND INPUT_VALUE_1 = #{inputValue1}


    AND OUTPUT_VALUE_1 = #{inputValue2}


    AND OUTPUT_VALUE_2 = #{inputValue3}


    AND OUTPUT_VALUE_3 = #{inputValue4}


    AND OUTPUT_VALUE_4 = #{inputValue5}

SELECT
    CUSTOMER_ID id,
    CUSTOMER_NAME text
FROM MST_CUSTOMER_INFO



        (
            CUSTOMER_NAME LIKE CONCAT('%', CONCAT(#{search}, '%'))
            OR
            CUSTOMER_ABBR LIKE CONCAT('%', CONCAT(#{search}, '%'))
            OR
            CUSTOMER_ID LIKE CONCAT('%', CONCAT(#{search}, '%'))
        )



        (
            CUSTOMER_NAME LIKE CONCAT('%', CONCAT(#{initValue}, '%'))
            OR
            CUSTOMER_ABBR LIKE CONCAT('%', CONCAT(#{initValue}, '%'))
            OR
            CUSTOMER_ID LIKE CONCAT('%', CONCAT(#{initValue}, '%'))
        )


        AND IS_ASSTE_MANAGER = #{IS_ASSTE_MANAGER}


        AND IS_TRUSTER = #{IS_TRUSTER}


        AND IS_ISSUER = #{IS_ISSUER}


        AND IS_FINANCIER = #{IS_FINANCIER}



        AND IS_GUARANTEE = #{IS_GUARANTEE}




        AND IS_INVEST_ADVISER = #{IS_INVEST_ADVISER}

select CALENDAR_ID id, CALENDAR_NAME text from MST_CALENDAR_INFO
and (CALENDAR_ID like concat(concat('%',#{search}),'%') or CALENDAR_NAME like concat(concat('%',#{search}),'%'))
and CALENDAR_ID = #{initValue}
